{"name": "create_gender_statistics_table", "query": "
-- ============================================================
-- TABLE 1: gender_statistics
-- Gender breakdown of total vs current employees and % share
-- ============================================================
CREATE TABLE IF NOT EXISTS employees.gender_statistics (
    gender                  VARCHAR(1)      NOT NULL,
    total_employees         INTEGER         NOT NULL,
    current_employees       INTEGER         NOT NULL,
    percentage_of_workforce DECIMAL(6, 2)   NOT NULL,
    CONSTRAINT pk_gender_statistics PRIMARY KEY (gender)
);

COMMENT ON TABLE  employees.gender_statistics IS 'Gender breakdown: total vs currently active employees and workforce percentage.';
COMMENT ON COLUMN employees.gender_statistics.gender                  IS 'Gender code: M = Male, F = Female.';
COMMENT ON COLUMN employees.gender_statistics.total_employees         IS 'Total number of employees of this gender (all time).';
COMMENT ON COLUMN employees.gender_statistics.current_employees       IS 'Currently active employees (those with an active salary record, to_date = 9999-01-01).';
COMMENT ON COLUMN employees.gender_statistics.percentage_of_workforce IS 'Percentage of the current workforce represented by this gender.';
"}

{"name": "create_age_group_analysis_table", "query": "
-- ============================================================
-- TABLE 2: age_group_analysis
-- Age-band breakdown of current employees with salary & tenure
-- ============================================================
CREATE TABLE IF NOT EXISTS employees.age_group_analysis (
    age_group       VARCHAR(10)     NOT NULL,
    employee_count  INTEGER         NOT NULL,
    avg_salary      DECIMAL(12, 2)  NOT NULL,
    avg_tenure_days DECIMAL(10, 2)  NOT NULL,
    CONSTRAINT pk_age_group_analysis PRIMARY KEY (age_group)
);

COMMENT ON TABLE  employees.age_group_analysis IS 'Age-group breakdown of current workforce with average salary and tenure metrics.';
COMMENT ON COLUMN employees.age_group_analysis.age_group       IS 'Age range band: 20-29, 30-39, 40-49, 50-59, or 60+.';
COMMENT ON COLUMN employees.age_group_analysis.employee_count  IS 'Number of currently active employees in this age group.';
COMMENT ON COLUMN employees.age_group_analysis.avg_salary      IS 'Average current salary for employees in this age group.';
COMMENT ON COLUMN employees.age_group_analysis.avg_tenure_days IS 'Average number of days of service (from hire_date to today) for employees in this age group.';
"}

