{"name": "create_birth_month_distribution_table", "query": "
-- ============================================================
-- TABLE 3: birth_month_distribution
-- Monthly birthday distribution across total & current staff
-- ============================================================
CREATE TABLE IF NOT EXISTS employees.birth_month_distribution (
    birth_month            INTEGER     NOT NULL,
    month_name             VARCHAR(12) NOT NULL,
    employee_count         INTEGER     NOT NULL,
    current_employee_count INTEGER     NOT NULL,
    CONSTRAINT pk_birth_month_distribution PRIMARY KEY (birth_month),
    CONSTRAINT chk_birth_month_range CHECK (birth_month BETWEEN 1 AND 12)
);

COMMENT ON TABLE  employees.birth_month_distribution IS 'Distribution of employee birth months (1-12) for total and currently active headcount.';
COMMENT ON COLUMN employees.birth_month_distribution.birth_month            IS 'Month number (1 = January … 12 = December).';
COMMENT ON COLUMN employees.birth_month_distribution.month_name             IS 'Full English month name (e.g. January).';
COMMENT ON COLUMN employees.birth_month_distribution.employee_count         IS 'Total employees (all time) born in this month.';
COMMENT ON COLUMN employees.birth_month_distribution.current_employee_count IS 'Currently active employees born in this month.';
"}

