{"name": "create_hiring_year_summary_table", "query": "
-- ============================================================
-- TABLE 4: hiring_year_summary
-- Yearly hiring cohort vs still-active headcount & retention
-- ============================================================
CREATE TABLE IF NOT EXISTS employees.hiring_year_summary (
    hire_year       INTEGER         NOT NULL,
    employees_hired INTEGER         NOT NULL,
    still_employed  INTEGER         NOT NULL,
    retention_rate  DECIMAL(6, 2)   NOT NULL,
    CONSTRAINT pk_hiring_year_summary PRIMARY KEY (hire_year)
);

COMMENT ON TABLE  employees.hiring_year_summary IS 'Annual hiring cohort summary showing how many from each year are still employed and the retention rate.';
COMMENT ON COLUMN employees.hiring_year_summary.hire_year       IS 'Calendar year in which employees were originally hired.';
COMMENT ON COLUMN employees.hiring_year_summary.employees_hired IS 'Total number of employees hired during this year.';
COMMENT ON COLUMN employees.hiring_year_summary.still_employed  IS 'Number from this cohort who are still currently employed (active salary record).';
COMMENT ON COLUMN employees.hiring_year_summary.retention_rate  IS 'Percentage of cohort still employed: (still_employed / employees_hired) * 100.';
"}

